/**
 * Shared contracts between every team. Owned by the Chief Engineer.
 *
 * Rules:
 *  - Teams build against these types and do not edit this file.
 *  - Need a change? Keep working with a local adapter and list the change in
 *    your final report. The Chief Engineer decides and applies it.
 *  - Each team exposes one factory from its folder's index.ts (see "Factories").
 */
import type { ZodType } from 'zod';
import type { ReasoningEffort } from './config.ts';

/* ------------------------------------------------------------------ */
/* Output columns                                                      */
/* ------------------------------------------------------------------ */

/** The six spreadsheet columns, in the customer's required order. */
export const FIELD_KEYS = ['name', 'position', 'company', 'email', 'phone', 'website'] as const;
export type FieldKey = (typeof FIELD_KEYS)[number];

export const COLUMN_HEADERS: Record<FieldKey, string> = {
  name: 'Name',
  position: 'Position',
  company: 'Company',
  email: 'Email',
  phone: 'Phone',
  website: 'Website',
};

/** One spreadsheet row. A blank cell is ''. Values are the exact final cell text. */
export type CardRow = Record<FieldKey, string>;

/** Joins several emails, phones or websites inside one cell. */
export const MULTI_VALUE_SEPARATOR = '; ';

/* ------------------------------------------------------------------ */
/* Jobs and files (stage 1)                                            */
/* ------------------------------------------------------------------ */

export type JobStatus = 'uploading' | 'queued' | 'running' | 'paused' | 'done' | 'cancelled';

/** Problems that retrying cannot fix. The job pauses and shows a Resume button. */
export type PauseReason = 'out_of_credit' | 'bad_api_key' | 'cost_cap' | 'user' | 'network';

export interface JobOptions {
  /** Uploads alternate front, back, front, back. Each pair becomes one card. */
  frontBackPairs: boolean;
  /** ISO country used to parse phones printed without a country code, e.g. 'IN'. */
  defaultCountry: string | null;
  costCapUsd: number;
}

export interface Job {
  id: string;
  name: string;
  createdAt: string;
  status: JobStatus;
  pauseReason: PauseReason | null;
  options: JobOptions;
}

export type FileStage =
  | 'received'
  | 'normalized'
  | 'quality_checked'
  | 'located'
  /** Terminal states. Every file must end in one of the next four. */
  | 'cropped'
  | 'duplicate'
  | 'no_card'
  | 'failed';

export interface SourceFile {
  id: string;
  jobId: string;
  /** Upload order, starting at 0. Used for front/back pairing. */
  seq: number;
  originalName: string;
  sha256: string;
  byteSize: number;
  storedPath: string;
  stage: FileStage;
  duplicateOfFileId: string | null;
  normalized: NormalizedImage | null;
  quality: QualityReport | null;
  locate: LocateResult | null;
  error: string | null;
}

export interface NewSourceFile {
  jobId: string;
  originalName: string;
  sha256: string;
  byteSize: number;
  storedPath: string;
}

/* ------------------------------------------------------------------ */
/* Vision (stages 2-5)                                                 */
/* ------------------------------------------------------------------ */

export interface NormalizedImage {
  /** JPEG or PNG on disk, upright per EXIF, sRGB. */
  path: string;
  width: number;
  height: number;
  sourceFormat: string;
}

/** location_uncertain: the card's box could not be trusted, so a person must look at it. */
export type QualityIssue = 'low_resolution' | 'blurry' | 'too_dark' | 'too_bright' | 'location_uncertain';

export interface QualityReport {
  /** False sends the card to human review. It is never rejected. */
  ok: boolean;
  width: number;
  height: number;
  blurScore: number;
  meanLuminance: number;
  issues: QualityIssue[];
}

export type Rotation = 0 | 90 | 180 | 270;

export interface CardLocation {
  /** Pixels in the normalized image. */
  box: { x: number; y: number; width: number; height: number };
  /** Clockwise rotation needed to make this card upright. */
  rotation: Rotation;
}

export interface LocateResult {
  /** True when both locate passes saw no card. The file ends as 'no_card', never dropped. */
  noCard: boolean;
  /** In reading order: top to bottom, then left to right. A single image can hold 30+ cards. */
  locations: CardLocation[];
  /** True when a bad or failed locate fell back to using the whole image. */
  fellBackToFullImage: boolean;
  /**
   * True only when two independent locate passes found the same cards. False means
   * a card may have been missed, so the file is shown to a person to check the count.
   */
  countConfirmed: boolean;
  note: string | null;
  /**
   * A person looked at the image and confirmed every card was found. Required
   * before copying for any image with 2+ cards, because a card missed by both
   * passes can't be caught automatically. Set only by the confirm-count route.
   */
  checkedByPerson?: boolean;
}

export type CardSide = 'single' | 'front' | 'back';

export interface CardCrop {
  path: string;
  width: number;
  height: number;
  side: CardSide;
  /**
   * Measured on this card's own native pixels, before any enlarging. This is what
   * decides review: a sharp photo of 30 cards can still give each card too few pixels.
   */
  quality: QualityReport;
}

/** One image per card side, for each of the three reads. */
export interface ReadImages {
  /** Natural colour crop. */
  A: string;
  /** Contrast-enhanced, sharpened crop. */
  B: string;
  /** Enlarged crop. */
  C: string;
}

export interface VisionService {
  normalize(input: { sourcePath: string; originalName: string; outDir: string }): Promise<NormalizedImage>;
  assessQuality(image: NormalizedImage): Promise<QualityReport>;
  /**
   * Runs two independent passes and reconciles them, so a card missed in one pass
   * is still found. Must not throw on a bad model answer: fall back to the full
   * image and say so. Must let JobPauseError propagate.
   */
  locate(image: NormalizedImage, ctx: LlmCallContext): Promise<LocateResult>;
  crop(image: NormalizedImage, locate: LocateResult, outDir: string): Promise<CardCrop[]>;
  prepareReadImages(crop: CardCrop, outDir: string): Promise<ReadImages>;
}

/* ------------------------------------------------------------------ */
/* Extraction (stage 6)                                                */
/* ------------------------------------------------------------------ */

export const READ_VARIANTS = ['A', 'B', 'C'] as const;
export type ReadVariant = (typeof READ_VARIANTS)[number];

/** What one read returns. Strings are exactly as printed. '' means not printed. */
export interface CardReadData {
  /** Every printed line, read before any field is chosen. */
  transcript: string[];
  name: string;
  position: string;
  company: string;
  emails: string[];
  phones: Array<{ number: string; label: string }>;
  websites: string[];
  /** Fields where something is printed but could not be read with certainty. */
  unreadable: FieldKey[];
}

export type ReadOutcome =
  | { ok: true; data: CardReadData }
  | { ok: false; failure: LlmFailure; detail: string };

export interface ReadRecord {
  cardId: string;
  variant: ReadVariant;
  outcome: ReadOutcome;
  model: string;
  usage: LlmUsage | null;
  createdAt: string;
}

export type Agreement = 'unanimous' | 'majority' | 'split';

export interface FieldConsensus {
  field: FieldKey;
  /** Final cell text from each read, in A, B, C order. null means that read failed. */
  values: Record<ReadVariant, string | null>;
  agreement: Agreement;
  /** The unanimous or majority value, or '' when split. */
  chosen: string;
  /** Distinct readings, most-supported first, for one-click review. */
  candidates: Array<{ value: string; reads: ReadVariant[] }>;
  /** True when any read marked this field unreadable. */
  unreadable: boolean;
}

export type FieldConsensusMap = Record<FieldKey, FieldConsensus>;

export interface ExtractionService {
  /** One read of one card. imagePaths has one image per side. Must not throw on a bad model answer. */
  readCard(input: { variant: ReadVariant; imagePaths: string[] }, ctx: LlmCallContext): Promise<ReadOutcome>;
  /** Compare all reads field by field. Pure function. Fewer than 3 good reads can never be 'unanimous'. */
  compare(reads: ReadRecord[]): FieldConsensusMap;
  /** Turn one read into its six final cell strings. Pure function. */
  toRow(data: CardReadData): CardRow;
}

/* ------------------------------------------------------------------ */
/* Validation and decision (stages 7-8)                                */
/* ------------------------------------------------------------------ */

export type CheckName =
  | 'verbatim'
  | 'agreement'
  | 'format'
  | 'real_domain'
  | 'near_miss'
  | 'unsafe_start'
  | 'unreadable'
  | 'quality'
  | 'missing_name'
  /** The same email appears on two cards from one image, so one may have read its neighbour. */
  | 'shared_on_sheet';

export interface CheckResult {
  check: CheckName;
  /** null for card-level checks. */
  field: FieldKey | null;
  passed: boolean;
  /** Plain-language explanation shown to the reviewer. */
  detail: string;
}

export type DecisionStatus = 'verified' | 'needs_review';

export interface CardDecision {
  status: DecisionStatus;
  /** Chosen values. For needs_review these are the pre-selected majority values. */
  row: CardRow;
  consensus: FieldConsensusMap;
  /** Every check that ran, passed or failed. */
  checks: CheckResult[];
  /** Fields a reviewer must look at. Empty when verified. */
  flaggedFields: FieldKey[];
}

export interface DecisionService {
  /** Verified requires 3 of 3 reads unanimous and every check passed. Anything else is needs_review. */
  decide(input: {
    reads: ReadRecord[];
    consensus: FieldConsensusMap;
    quality: QualityReport | null;
    defaultCountry: string | null;
  }): Promise<CardDecision>;
}

/* ------------------------------------------------------------------ */
/* Cards                                                               */
/* ------------------------------------------------------------------ */

export type CardStage = 'created' | 'prepared' | 'reading' | 'decided';

/**
 * verified / confirmed cards are the only ones that can be copied.
 * pending: pipeline still working. failed: pipeline gave up, card is listed for the user.
 */
export type CardStatus = 'pending' | 'verified' | 'needs_review' | 'confirmed' | 'rejected' | 'failed';

export interface Card {
  id: string;
  jobId: string;
  /** One file normally, two for a front/back pair. */
  sourceFileIds: string[];
  /** Position of this card within its source image. */
  indexInSource: number;
  stage: CardStage;
  status: CardStatus;
  crops: CardCrop[];
  /** One ReadImages per crop, in the same order as crops. */
  readImages: ReadImages[];
  decision: CardDecision | null;
  /** Final row. Set when verified, or by a person when confirmed. */
  finalRow: CardRow | null;
  confirmedByHuman: boolean;
  /** Set when another card in this job looks like the same person. Both rows stay. */
  possibleDuplicateOf: string | null;
  error: string | null;
}

export interface NewCard {
  jobId: string;
  sourceFileIds: string[];
  indexInSource: number;
  crops: CardCrop[];
}

/** The on-screen count. balanced must always be true when a job is done. */
export interface Reconciliation {
  files: number;
  duplicateFiles: number;
  noCardFiles: number;
  failedFiles: number;
  filesInProgress: number;
  cards: number;
  verified: number;
  confirmed: number;
  needsReview: number;
  rejected: number;
  failedCards: number;
  cardsInProgress: number;
  /** Every file and card is accounted for in exactly one bucket. */
  balanced: boolean;
}

/* ------------------------------------------------------------------ */
/* Storage                                                             */
/* ------------------------------------------------------------------ */

/** Synchronous, backed by node:sqlite. Every write is durable when it returns. */
export interface Store {
  createJob(input: { name: string; options: JobOptions }): Job;
  getJob(id: string): Job | undefined;
  listJobs(): Job[];
  setJobStatus(id: string, status: JobStatus, pauseReason?: PauseReason | null): void;
  /** A person raised the spending cap, so a job paused at the cap can resume. */
  setJobCostCap(id: string, costCapUsd: number): void;
  deleteJob(id: string): void;

  /** Assigns seq. An exact sha256 match in the same job is stored with stage 'duplicate'. */
  addFile(input: NewSourceFile): SourceFile;
  getFile(id: string): SourceFile | undefined;
  listFiles(jobId: string): SourceFile[];
  updateFile(id: string, patch: Partial<Pick<SourceFile, 'stage' | 'normalized' | 'quality' | 'locate' | 'error'>>): void;

  createCard(input: NewCard): Card;
  getCard(id: string): Card | undefined;
  listCards(jobId: string, filter?: { status?: CardStatus }): Card[];
  updateCard(
    id: string,
    patch: Partial<Pick<Card, 'stage' | 'status' | 'crops' | 'readImages' | 'decision' | 'finalRow' | 'error' | 'possibleDuplicateOf'>>,
  ): void;

  /** Upsert on (cardId, variant), so resume never loses or duplicates a read. */
  saveRead(record: ReadRecord): void;
  listReads(cardId: string): ReadRecord[];

  recordLlmCall(entry: LlmLedgerEntry): void;
  getJobSpendUsd(jobId: string): number;

  /** A person confirmed the card, possibly after editing values. */
  confirmCard(cardId: string, row: CardRow): void;
  rejectCard(cardId: string, reason: string): void;

  /** Rows for verified and confirmed cards only, ordered by file seq, then indexInSource. */
  getCopyableRows(jobId: string): Array<{ cardId: string; row: CardRow }>;
  getReconciliation(jobId: string): Reconciliation;
  /**
   * Mark cards sharing an email or phone, keeping both rows. Also, when two cards
   * from the SAME source file share an email, moves every verified one to
   * needs_review with a failed shared_on_sheet check, because a card may have read
   * its neighbour's text. Never changes a card a person confirmed. Safe to re-run.
   */
  markPossibleDuplicates(jobId: string): void;
  close(): void;
}

/* ------------------------------------------------------------------ */
/* OpenAI client                                                       */
/* ------------------------------------------------------------------ */

export type LlmPurpose = 'locate' | 'orient' | 'read_a' | 'read_b' | 'read_c';

export interface LlmCallContext {
  jobId: string;
  purpose: LlmPurpose;
  cardId?: string;
  fileId?: string;
  signal?: AbortSignal;
}

export interface LlmUsage {
  inputTokens: number;
  cachedInputTokens: number;
  outputTokens: number;
  reasoningTokens: number;
  costUsd: number;
}

/** Handled per card: retried, then sent to review. Never becomes a guessed value. */
export type LlmFailure = 'refused' | 'incomplete' | 'schema_invalid' | 'retries_exhausted';

export interface LlmParseRequest<T> {
  instructions: string;
  userText: string;
  /** Local image files, sent as base64 data URLs with detail from CONFIG.imageDetail. */
  imagePaths: string[];
  schema: ZodType<T>;
  schemaName: string;
  reasoningEffort: ReasoningEffort;
  maxOutputTokens: number;
}

export type LlmParseResult<T> =
  | { ok: true; value: T; model: string; usage: LlmUsage; latencyMs: number; attempts: number }
  | { ok: false; failure: LlmFailure; detail: string; usage: LlmUsage | null; latencyMs: number; attempts: number };

export interface LlmClient {
  /**
   * Handles rate limiting, ramp-up, retries, usage accounting and the ledger.
   * Returns ok:false for per-card problems. Throws JobPauseError for problems
   * that retrying cannot fix, so the engine can pause the whole job.
   */
  parse<T>(request: LlmParseRequest<T>, ctx: LlmCallContext): Promise<LlmParseResult<T>>;
}

export interface LlmLedgerEntry {
  jobId: string;
  cardId: string | null;
  fileId: string | null;
  purpose: LlmPurpose;
  model: string;
  ok: boolean;
  failure: LlmFailure | null;
  attempts: number;
  latencyMs: number;
  usage: LlmUsage | null;
  createdAt: string;
}

/** Thrown by LlmClient. The engine catches it and pauses the job. */
export class JobPauseError extends Error {
  readonly reason: PauseReason;
  constructor(reason: PauseReason, message: string) {
    super(message);
    this.name = 'JobPauseError';
    this.reason = reason;
  }
}

/* ------------------------------------------------------------------ */
/* Job engine                                                          */
/* ------------------------------------------------------------------ */

export interface JobProgress {
  jobId: string;
  status: JobStatus;
  pauseReason: PauseReason | null;
  reconciliation: Reconciliation;
  spendUsd: number;
  costCapUsd: number;
  cardsPerMinute: number;
  etaSeconds: number | null;
  concurrency: number;
}

export interface JobEngine {
  /** Start or continue a job. Completed stages are skipped and never billed twice. */
  start(jobId: string): void;
  pause(jobId: string): void;
  resume(jobId: string): void;
  cancel(jobId: string): void;
  getProgress(jobId: string): JobProgress;
  /** Called on boot: resumes every job left 'running' or 'queued'. */
  recover(): void;
  subscribe(listener: (progress: JobProgress) => void): () => void;
  /** Stop cleanly. In-flight work is abandoned safely and redone on the next start. */
  shutdown(): Promise<void>;
}

/* ------------------------------------------------------------------ */
/* Paste and export (stage 10)                                         */
/* ------------------------------------------------------------------ */

export interface ClipboardPayload {
  html: string;
  plain: string;
}

export interface VerifyPasteDifference {
  /** 1-based row within the pasted data, ignoring any header. */
  row: number;
  field: FieldKey;
  expected: string;
  actual: string;
  /** e.g. 'formula_error', 'lost_plus', 'lost_leading_zero', 'scientific_notation', 'date', 'changed'. */
  kind: string;
}

export interface VerifyPasteReport {
  ok: boolean;
  rowsExpected: number;
  rowsFound: number;
  cellsCompared: number;
  differences: VerifyPasteDifference[];
}

export interface PasteService {
  encode(rows: CardRow[], options: { includeHeader: boolean }): ClipboardPayload;
  /** Writes the Mac clipboard directly, reads it back and confirms the bytes match. */
  writeClipboard(payload: ClipboardPayload): Promise<{ verified: boolean; detail: string }>;
  readClipboard(): Promise<ClipboardPayload>;
  /** Compares text copied back out of a spreadsheet with what should be there. */
  verifyPaste(expected: CardRow[], pastedText: string): VerifyPasteReport;
}

/* ------------------------------------------------------------------ */
/* Factories: what each folder's index.ts must export                  */
/* ------------------------------------------------------------------ */

export type CreateStore = (dbPath: string) => Store;
export type CreateLlmClient = (options: {
  apiKey: string;
  /** Overrides the API address. QA's fake server uses this. */
  baseURL?: string;
  /** Records usage. In production this is store.recordLlmCall. */
  onCall: (entry: LlmLedgerEntry) => void;
  /** Lets the client enforce the job's cost cap. */
  getSpendUsd: (jobId: string) => number;
  getCostCapUsd: (jobId: string) => number;
}) => LlmClient;
export type CreateVisionService = (deps: { llm: LlmClient }) => VisionService;
export type CreateExtractionService = (deps: { llm: LlmClient }) => ExtractionService;
export type CreateDecisionService = (deps: {
  /** Injected so tests never touch real DNS. Omit for real lookups. */
  resolveDomain?: (domain: string, kind: 'email' | 'website') => Promise<'exists' | 'missing' | 'unknown'>;
}) => DecisionService;
export type CreatePasteService = () => PasteService;
export type CreateJobEngine = (deps: {
  store: Store;
  vision: VisionService;
  extraction: ExtractionService;
  decision: DecisionService;
  /** Root folder for per-job working images. */
  jobsDir: string;
}) => JobEngine;
/** Export functions from src/export/index.ts. */
export type ToXlsx = (rows: CardRow[]) => Promise<Buffer>;
export type ToCsv = (rows: CardRow[]) => Buffer;

/* ------------------------------------------------------------------ */
/* Wire formats: what the model returns                                */
/* ------------------------------------------------------------------ */

/**
 * Structured-output schema names, sent as text.format.name. The QA fake server
 * routes on these, so Vision and Extraction must use them exactly.
 */
export const SCHEMA_NAMES = { locate: 'card_locations', orient: 'card_orientation', read: 'card_read' } as const;

/**
 * Locate pass output. Coordinates are normalised 0-1000 across the image that
 * was sent, so they survive any resizing. Vision maps them back to pixels.
 */
export interface LocateWireResult {
  contains_card: boolean;
  cards: Array<{ x_min: number; y_min: number; x_max: number; y_max: number; rotation: Rotation }>;
}

/** Read pass output is exactly CardReadData, with transcript as the first key. */
export type ReadWireResult = CardReadData;
